{"Table":"bk_tb_categories","Create Table":"CREATE TABLE `bk_tb_categories` (\n  `id` varchar(36) NOT NULL,\n  `name` varchar(255) NOT NULL,\n  `category` varchar(255) DEFAULT NULL,\n  `owner` varchar(255) NOT NULL,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  `positive` tinyint(1) NOT NULL,\n  `internal` tinyint(1) NOT NULL DEFAULT 0,\n  `classification` varchar(255) DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  KEY `FK_category_owner` (`owner`),\n  KEY `FK_category_group` (`category`),\n  KEY `idx_category_positive` (`id`,`positive`),\n  KEY `idx_category_subcategory` (`id`,`category`),\n  CONSTRAINT `FK_category_group` FOREIGN KEY (`category`) REFERENCES `bk_tb_categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,\n  CONSTRAINT `FK_category_owner` FOREIGN KEY (`owner`) REFERENCES `bk_tb_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","json":{"name":"bk_tb_categories.sql","path":"files/sql/rod/bk_tb_categories.sql","sha":"f286d8e96eaa4b998b40efee76d67ea3c22d52e0","size":21135,"url":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/bk_tb_categories.sql?ref=master","html_url":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/bk_tb_categories.sql","git_url":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/f286d8e96eaa4b998b40efee76d67ea3c22d52e0","download_url":"https://raw.githubusercontent.com/rodcordeiro/shares/master/files/sql/rod/bk_tb_categories.sql","type":"file","content":"eyJUYWJsZSI6ImJrX3RiX2NhdGVnb3JpZXMiLCJDcmVhdGUgVGFibGUiOiJD\nUkVBVEUgVEFCTEUgYGJrX3RiX2NhdGVnb3JpZXNgIChcbiAgYGlkYCB2YXJj\naGFyKDM2KSBOT1QgTlVMTCxcbiAgYG5hbWVgIHZhcmNoYXIoMjU1KSBOT1Qg\nTlVMTCxcbiAgYGNhdGVnb3J5YCB2YXJjaGFyKDI1NSkgREVGQVVMVCBOVUxM\nLFxuICBgb3duZXJgIHZhcmNoYXIoMjU1KSBOT1QgTlVMTCxcbiAgYGNyZWF0\nZWRfYXRgIHRpbWVzdGFtcCBOT1QgTlVMTCBERUZBVUxUIGN1cnJlbnRfdG